let msg_id = msg.msg_id

let retry_limit = context.get("retry_limit")
let current_id = context.get("current_id")
let retries = context.get("retries")

// reset if new message
if (!current_id || current_id !== msg_id) {
    context.set("current_id", msg_id)
    context.set("retries", 2)
    return [null, msg]
}

// retry until retry_limit reached
if (current_id == msg_id) {
    if (retries <= retry_limit) {
        context.set("retries", retries +1)
        return [null, msg]
    } else if (retries > retry_limit) {
        context.set("retries", 0)
        context.set("current_id", "")
        return [msg, null]
    }
}

